                <span className="font-medium">{u.staffName}</span>
                <span className="text-zinc-500">
                  {Math.round(u.bookedMinutes / 60)} h of {Math.round(u.availableMinutes / 60)} h ·{" "}
                  {kzt(u.revenue)}
