            </thead>
            <tbody>
              {clients.map((c) => (
                <tr key={c.phone} className="border-b border-zinc-100 last:border-0">
                  <td className="p-3 text-zinc-400">{c.rank}</td>
                  <td className="p-3 font-medium">
                    {c.name} <span className="font-normal text-zinc-500">{c.phone}</span>
