                  <td className="p-3 text-right">{c.visits}</td>
                  <td className="p-3 text-right">{kzt(c.revenue)}</td>
                  <td className="p-3 text-right text-zinc-500">{pct(c.cumulativeShare)}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </section>
    </div>
  );
}
