                <span className="text-zinc-500">→ {m.recipient}</span>
                <span className="ml-auto text-xs text-zinc-400">{fmt.format(m.createdAt)}</span>
              </div>
              <p className="mt-1 text-zinc-600">{m.body}</p>
            </article>
          ))}
        </div>
      </section>
    </div>
  );
