import { db, schema as s } from "@/db";
import { requireSession } from "@/lib/session";

const statusStyle: Record<string, string> = {
  pending: "bg-amber-100 text-amber-800",
  processing: "bg-sky-100 text-sky-800",
  sent: "bg-emerald-100 text-emerald-800",
  dead: "bg-red-100 text-red-800",
  cancelled: "bg-zinc-200 text-zinc-600",
};

export default async function NotificationsPage() {
  const session = await requireSession();

  const queue = await db
    .select()
    .from(s.outbox)
    .where(eq(s.outbox.businessId, session.businessId))
    .orderBy(desc(s.outbox.createdAt))
    .limit(50);

  const delivered = await db
    .select()
    .from(s.messageLog)
    .where(eq(s.messageLog.businessId, session.businessId))
    .orderBy(desc(s.messageLog.createdAt))
    .limit(50);

  const fmt = new Intl.DateTimeFormat("en-GB", { dateStyle: "short", timeStyle: "short" });
  const counts = queue.reduce<Record<string, number>>((acc, r) => {
    acc[r.status] = (acc[r.status] ?? 0) + 1;
    return acc;
  }, {});

  return (
    <div className="space-y-6">
      <div>
        <h1 className="text-xl font-semibold">Notifications</h1>
        <p className="mt-1 text-sm text-zinc-500">
          Messages are queued inside the same transaction as the booking itself and delivered by a separate
          worker (<code className="rounded bg-zinc-100 px-1">pnpm worker</code>).
        </p>
      </div>

      <div className="flex flex-wrap gap-2 text-sm">
        {Object.entries(counts).map(([status, n]) => (
          <span key={status} className={`rounded-full px-3 py-1 ${statusStyle[status]}`}>
            {status}: {n}
          </span>
        ))}
        {queue.length === 0 && <span className="text-zinc-400">Queue is empty</span>}
      </div>

      <section>
        <h2 className="mb-2 font-medium text-zinc-700">Queue</h2>
        <div className="overflow-x-auto rounded-xl border border-zinc-200 bg-white">
          <table className="w-full text-sm">
            <thead className="border-b border-zinc-200 text-left text-zinc-500">
              <tr>
                <th className="p-3">Subject</th>
                <th className="p-3">Status</th>
                <th className="p-3 text-right">Attempts</th>
                <th className="p-3">Send at</th>
                <th className="p-3">Error</th>
              </tr>
            </thead>
            <tbody>
              {queue.map((r) => (
                <tr key={r.id} className="border-b border-zinc-100 last:border-0">
                  <td className="p-3 font-mono text-xs">{r.topic}</td>
                  <td className="p-3">
                    <span className={`rounded px-2 py-0.5 text-xs ${statusStyle[r.status]}`}>
                      {r.status}
                    </span>
